/// <reference lib="webworker" />
/**
 * The pathfinder, off the page's thread: nav-web (the engine compiled to WebAssembly by TeaVM) plus
 * the world snapshot the bake wrote, both served beside the site under `api/nav/`. Each request is
 * one synchronous call into the module, so requests are answered strictly in turn.
 *
 * Messages in: `{id, op, json?, baked?}` with op `world` (download and read the world; `baked` is
 * the bake's timestamp) | `pathfinder` (build it) | `items` | `wearables` (the ids that may be
 * worn) | `inputs` | `plan` | `preview` (a plan with the walk only) | `account` |
 * `reachable` | `serverWorld` (what the page needs to play the server: spawns, definitions and the
 * walk graph) | `serverTransports` (the transports as it runs them) | `walkStart` (start walking a
 * request) | `walkTick` (one tick of it, from `view`).
 * Messages out: `{id, ok: true, value}` or `{id, ok: false, error}`, and while the world loads,
 * `{progress}` naming the stage it has reached (the Java side posts most of them itself).
 */
import {asset} from "../api";

interface NavExports {
    main(args: string[]): void;
    loadWorld(gzippedSnapshot: Int8Array): string;
    buildPathfinder(): string;
    itemNames(): string;
    wearableItems(): string;
    inputs(): string;
    plan(json: string): string;
    preview(json: string): string;
    account(json: string): string;
    reachable(json: string): string;
    serverWorld(): string;
    stepMap(): Int8Array | null;
    walkStart(json: string): string;
    walkTick(x: number, z: number, inCombat: boolean, npcs: Int32Array): string;
    serverTransports(): string;
}

export type NavOp =
    | "world"
    | "pathfinder"
    | "items"
    | "inputs"
    | "plan"
    | "preview"
    | "account"
    | "wearables"
    | "reachable"
    | "serverWorld"
    | "serverTransports"
    | "walkStart"
    | "walkTick";

export interface NavRequest {
    id: number;
    op: NavOp;
    json?: string;
    /** The bake's timestamp ({@code manifest.baked}), with `world`. */
    baked?: number;
    /** What the bot sees, with `walkTick`. */
    view?: {x: number; z: number; inCombat: boolean; npcs: Int32Array};
}

export type NavReply = {id: number; ok: true; value: unknown} | {id: number; ok: false; error: string};

/** A load stage, posted as it starts. */
export interface NavProgress {
    progress: string;
    /** When it started, on the worker's clock. */
    at: number;
}

/**
 * The engine and the world are baked together and must match (the snapshot carries a format
 * version the engine checks), but their file names never change between bakes. So every request
 * carries the bake's timestamp, as the mesh cells and textures do: within a bake the browser caches
 * them as usual, and a new bake asks for new URLs — a stale world beside a new engine reads as
 * "snapshot version N, this reads M".
 */
let baked = 0;
const url = (path: string) => `${new URL(asset(path), self.location.href).href}?v=${baked}`;

const download = async (path: string): Promise<ArrayBuffer> => {
    const r = await fetch(url(path));
    if (!r.ok) throw new Error(`${path} → ${r.status}`);
    return r.arrayBuffer();
};

let nav: Promise<NavExports> | null = null;

/** The part of TeaVM's wasm-gc runtime module this worker uses. */
interface TeaVmRuntime {
    load(wasm: ArrayBuffer): Promise<{exports: unknown}>;
}

function module(): Promise<NavExports> {
    nav ??= (async () => {
        const runtime = (await import(/* @vite-ignore */ url("/api/nav/wasm-gc-module-runtime.js"))) as TeaVmRuntime;
        const teavm = await runtime.load(await download("/api/nav/nav.wasm"));
        const x = teavm.exports as NavExports;
        x.main([]);
        return x;
    })();
    return nav;
}

/** A module answer: JSON, or `{"error": …}` when the Java side threw. */
function parsed(text: string): unknown {
    const value: unknown = JSON.parse(text);
    if (value && typeof value === "object" && "error" in value && Object.keys(value).length === 1) {
        throw new Error(String(value.error));
    }
    return value;
}

async function answer(req: NavRequest): Promise<unknown> {
    if (req.op === "world") {
        baked = req.baked ?? 0;
        const t0 = performance.now();
        self.postMessage({
            progress: "downloading the pathfinder and the world",
            at: performance.now(),
        } satisfies NavProgress);
        const [x, snapshot] = await Promise.all([module(), download("/api/nav/world.snap.gz")]);
        const t1 = performance.now();
        const info = parsed(x.loadWorld(new Int8Array(snapshot))) as Record<string, unknown>;
        return {
            ...info,
            fetchMs: Math.round(t1 - t0),
            totalMs: Math.round(performance.now() - t0),
            doneAt: performance.now(),
        };
    }
    const x = await module();
    switch (req.op) {
        case "pathfinder": {
            const t0 = performance.now();
            const info = parsed(x.buildPathfinder()) as Record<string, unknown>;
            return {...info, doneAt: performance.now(), totalMs: Math.round(performance.now() - t0)};
        }
        case "items":
            return parsed(x.itemNames());
        case "wearables":
            return parsed(x.wearableItems());
        case "inputs":
            return parsed(x.inputs());
        case "plan":
            return parsed(x.plan(req.json ?? "{}"));
        case "preview":
            return parsed(x.preview(req.json ?? "{}"));
        case "account":
            return parsed(x.account(req.json ?? "{}"));
        case "reachable":
            return parsed(x.reachable(req.json ?? "{}"));
        case "serverWorld": {
            const world = parsed(x.serverWorld());
            const steps = x.stepMap();
            if (!steps) throw new Error("no world loaded");
            return {world, steps};
        }
        case "serverTransports":
            return parsed(x.serverTransports());
        case "walkStart":
            return parsed(x.walkStart(req.json ?? "{}"));
        case "walkTick": {
            const v = req.view;
            if (!v) throw new Error("walkTick without a view");
            return parsed(x.walkTick(v.x, v.z, v.inCombat, v.npcs));
        }
    }
}

// One at a time, in arrival order: an async step (the first fetch) must not let a later request
// run against a module that has not loaded its world yet.
let queue: Promise<unknown> = Promise.resolve();

self.onmessage = (e: MessageEvent<NavRequest>) => {
    const req = e.data;
    queue = queue
        .then(() => answer(req))
        .then(
            (value) =>
                self.postMessage(
                    {id: req.id, ok: true, value} satisfies NavReply,
                    // The walk graph is megabytes: handed over, not copied.
                    {
                        transfer:
                            req.op === "serverWorld" ? [(value as {steps: Int8Array}).steps.buffer as ArrayBuffer] : [],
                    },
                ),
            (err: unknown) =>
                self.postMessage({
                    id: req.id,
                    ok: false,
                    error: err instanceof Error ? err.message : String(err),
                } satisfies NavReply),
        );
};
