/**
 * Open-source viewer data layer.
 *
 * The World3DView component is data-source agnostic: it renders whatever entity
 * data it's handed via props and fetches its static world assets from
 * `/api/world3d/*` + `/api/map/*`. This module provides:
 *
 *   - the shared entity/asset TYPES (mirrors of the server DTOs),
 *   - the static asset FETCHERS (plain GETs a dumb HTTP host answers), and
 *   - STUBBED control verbs (`sendWalk`/`sendInteract`): the open-source build
 *     has nothing to control, so they no-op. A closed-source build wires these
 *     to a live server via `configureViewerHost`.
 *
 * Player sprites need no server at all: any appearance token is composited in
 * the browser from the per-layer atlas (see `playerLayerAtlas`).
 */

import type {World3DViewProps} from "./World3DView";

/**
 * Prefix an absolute asset("/api/...") path with the deploy base (Vite's BASE_URL),
 * so the viewer works both at a domain root ("/") and under a GitHub *project*
 * Pages subpath ("/<repo>/"). Set the base via VITE_BASE at build time.
 */
export function asset(path: string): string {
    return import.meta.env.BASE_URL.replace(/\/$/, "") + path;
}

// ---------------------------------------------------------------------------
// Entity + asset types (mirror the server DTOs the viewer consumes)

export interface BotPosition {
    x: number;
    z: number;
    floor: number;
}

/**
 * One thing in a bot's local view — an npc, player, scenery object, wall/gate,
 * or ground item. `serverIndex` is the server's stable handle for it (and the
 * dedup key when several observers see it at once); most fields are optional —
 * send only what you know.
 */
export interface MapEntity {
    /** Server's stable id for this entity — the dedup key across observers. */
    serverIndex: number;
    /** Definition id: npc id, item id, or scenery id; `0` for players. */
    id: number;
    /** Display name, or `null` to fall back to the definition's own name. */
    name: string | null;
    /** Tile X. */
    x: number;
    /**
     * Tile Z, **absolute** — the floor is folded in: `z = tileZ + floor*944`
     * (floor 0 = ground … 3 = underground).
     */
    z: number;
    /** Whether it's currently fighting (tints the nameplate). */
    inCombat: boolean;
    /** Tile-edge direction for wall/boundary objects; facing for scenery. */
    dir?: number | null;
    /**
     * Players only — the RSC appearance packet as a token ({@link Appearance}),
     * composited into a sprite in the browser. Build/read it with
     * {@link formatAppearance} / {@link parseAppearance}.
     */
    appearance?: string | null;
    /** Players only — combat level shown on the nameplate. */
    combatLvl?: number | null;
    /** Players only — draws the PK-skull icon. */
    skulled?: boolean;
    /** Current hitpoints (with {@link MapEntity.maxHp}, draws a health bar). */
    hp?: number | null;
    /** Maximum hitpoints. */
    maxHp?: number | null;
    /** Damage just taken (`0` = a blocked hit); flashes a hit splat at {@link MapEntity.dmgTick}. */
    dmg?: number | null;
    /** The server tick {@link MapEntity.dmg} landed on (so each hit splats exactly once). */
    dmgTick?: number | null;
    /** Latest overhead chat line, shown as a bubble at {@link MapEntity.msgTick}. */
    msg?: string | null;
    /** The server tick {@link MapEntity.msg} was said. */
    msgTick?: number | null;
    /** Action-bubble item id (small nameplate icon), popped at {@link MapEntity.bubbleTick}. */
    bubble?: number | null;
    /** The server tick {@link MapEntity.bubble} popped. */
    bubbleTick?: number | null;
    /** NPCs and players — the ground ring's own colour (0xRRGGBB), to mark this one out (a search
     *  hit, a target). The ring follows the sprite as it glides, so this marks a walker smoothly where
     *  an overlay on its tile would jump a tile a tick. Hover, selection and combat still override it,
     *  unless {@link MapEntity.ringColorFirst}; hovered, it also grows a little, so the hover
     *  shows whatever colour you chose. */
    ringColor?: number;
    /** {@link MapEntity.ringColor} outranks the combat colour too. */
    ringColorFirst?: boolean;
    /** NPCs and players — the nameplate's fill (0xRRGGBB), with dark text, in place of its kind's
     *  look: a plate that stands out from the rest. */
    tagColor?: number;
    /** NPCs and players — show the nameplate whatever the tags toggle and the zoom tier say: one
     *  the host is pointing at. The plate follows the sprite and stacks with its neighbours'. */
    tagAlways?: boolean;
    /** NPCs and players — an outline round the nameplate (0xRRGGBB): one of a set the host marks
     *  (search hits). Hover and selection outlines win over it. */
    tagOutline?: number;
}

/**
 * A player's on-screen appearance — the RSC appearance record, one-to-one with
 * what the server's player-appearance packet carries:
 *
 *  - `sprites`: the worn-sprite array, one animation id per appearance slot, in
 *    draw order. `0` = empty slot; a non-zero value is `animationId + 1` (the
 *    +1 keeps 0 free for "nothing"). These already encode the whole outfit —
 *    equipping an item is the server swapping the sprite id in that item's slot,
 *    so there are no separate "item ids" to resolve. Slots 3/4 are weapon/shield;
 *    the rest are the head/body/legs base and armour overrides. Up to 12 slots.
 *  - `hair`/`top`/`bottom`/`skin`: palette indices (not RGB) into the hair,
 *    clothing, clothing and skin ramps — the four colour choices the packet sends.
 *
 * On the wire and on {@link MapEntity.appearance} this is serialized to the
 * compact string `"s0,s1,…|hair,top,bottom,skin"` (e.g. `"4,5,3|1,12,2,3"`): it
 * is one small field per entity per tick and doubles as the compositor's cache
 * key. {@link formatAppearance}/{@link parseAppearance} convert to/from it.
 */
export interface Appearance {
    /** Worn-sprite animation ids per slot (0 = empty), the RSC appearance array. */
    sprites: number[];
    /** Palette index into the hair-colour ramp. */
    hair: number;
    /** Palette index into the clothing ramp (shirt / torso). */
    top: number;
    /** Palette index into the clothing ramp (trousers / legs). */
    bottom: number;
    /** Palette index into the skin ramp. */
    skin: number;
}

/** Serialize an {@link Appearance} to the `"sprites|hair,top,bottom,skin"` token. */
export function formatAppearance(a: Appearance): string {
    return a.sprites.join(",") + "|" + [a.hair, a.top, a.bottom, a.skin].join(",");
}

/** Parse a `"sprites|hair,top,bottom,skin"` token into an {@link Appearance}. */
export function parseAppearance(token: string): Appearance {
    const [l = "", c = ""] = token.split("|");
    const sprites = l ? l.split(",").map((n) => parseInt(n, 10) || 0) : [];
    const [hair = 0, top = 0, bottom = 0, skin = 0] = c.split(",").map((n) => parseInt(n, 10) || 0);
    return {sprites, hair, top, bottom, skin};
}

/**
 * One observer's slim per-tick view: its own vitals plus its local view of the
 * npcs / players / objects / walls / ground items around it. An observer is a
 * live vantage point onto the world — one of your bots, or (to mirror a whole
 * server) every online player. Fed to the viewer as the `observers` prop; the
 * open-source demo synthesizes these, a live app streams them (one snapshot per
 * server tick — the viewer interpolates between ticks). Multiple observers are
 * merged into one world, deduped by `serverIndex` (npcs/players) and tile
 * (ground items / scenery).
 */
/**
 * Everything the observers can see between them, deduplicated: one entry per thing, not one per
 * (thing, observer who sees it).
 *
 * Deduplicating is the feed's job rather than the view's. Observers overlap heavily — a crowded
 * bank is the same forty players in eight lists — and whoever assembles the feed already knows
 * which sighting is freshest, where the view could only guess by taking the first one it met and
 * patching later chat onto it. Tile z is ABSOLUTE, floor folded in.
 */
export interface WorldEntities {
    npcs: MapEntity[];
    players: MapEntity[];
    /** Live scenery — a mined rock, an opened chest — overriding the static bake. */
    objects: MapEntity[];
    /** Doors and gates, addressed by tile-edge (their `dir`). */
    wallObjects: MapEntity[];
    groundItems: MapEntity[];
}

/** One vantage point on the world: where it is, how it is, and what it did this tick. What it can
 *  SEE arrives separately, pooled across every observer, as {@link WorldEntities}. */
export interface Observer {
    /** The observer's account name — its stable key in the `observers` array. */
    username: string;
    /** Free-text run status (e.g. `"online"`). Host UI only; ignored by the viewer. */
    status: string;
    /** The script class driving this observer (bot runs only), or `null`. Host UI only. */
    scriptClass: string | null;
    /** Human-readable current task, if any. Host UI only. */
    task?: string | null;
    /** Longer status / description line. Host UI only. */
    description: string | null;
    /** This observer's current server tick — stamps the timed events below. */
    serverTick: number | null;
    /** The observer's own tile + floor; `null` = it draws no sprite of its own. */
    position: BotPosition | null;
    /** This vantage point is no longer live — `position` is the tile it was last seen on rather
     *  than where it is now. Drawn as a faded ghost: translucent sprite, greyed nameplate, no
     *  ring, no health bar, and its sightings are not treated as current. Omit (or `false`) for a
     *  live observer. The host decides what counts as offline; the viewer only renders it. */
    offline?: boolean;
    /** Fatigue, 0–100. Host UI only. */
    fatiguePercent: number | null;
    /** Whether the observer is asleep (Zzz on the nameplate). */
    sleeping: boolean | null;
    /** Whether the observer is in combat (tints the nameplate). */
    inCombat: boolean | null;
    /** The observer's own server index, so it isn't re-drawn as a "player" it sees. */
    serverIndex?: number;
    /** Changes when the position jumps (a walk restarted from its start): placed, not glided.
     *  Between changes the observer glides as any other. */
    snapSeq?: number;
    /** This observer's ring in a colour of its own (0xRRGGBB) instead of the bots' blue. Hovered,
     *  it also grows a little, so the hover shows whatever colour you chose. */
    ringColor?: number;
    /** {@link ringColor} outranks the offline and combat ring colours (hover and selection still
     *  win) — for a ring marking something that must stay visible in any state. */
    ringColorFirst?: boolean;
    /** This observer's own appearance token ({@link Appearance}) — drives its sprite. */
    appearance?: string | null;
    /** The observer's facing, 0–7. */
    dir?: number | null;
    /** The observer's current hitpoints (with {@link Observer.maxHits}, draws its health bar). */
    hits?: number | null;
    /** True while the bot displays a PK skull — its nameplate gets the same
     *  skull prefix as foreign players'. */
    skulled?: boolean;
    /** The observer's maximum hitpoints. */
    maxHits?: number | null;
    /** Damage just dealt to the observer (`0` = blocked); flashes a splat at {@link Observer.serverTick}. */
    dmg?: number | null;
    /** Server session id. Host UI only. */
    sessionId?: number | null;
    /** The observer's latest overhead chat line (bubble at {@link Observer.msgTick}). */
    msg?: string | null;
    /** The server tick {@link Observer.msg} was said. */
    msgTick?: number | null;
    /** The observer's action-bubble item id (nameplate icon), popped at {@link Observer.bubbleTick}. */
    bubble?: number | null;
    /** The server tick {@link Observer.bubble} popped. */
    bubbleTick?: number | null;
    /** Projectiles (arrows / spells) launched this tick — each animates once, then is gone. */
    projectiles?: {
        /** Which projectile sprite: 0 orb, 1 magic, 2 ranged, 3 gnomeball, 4 skull, 5 spikeball. */
        sprite: number;
        /** The shooter's `serverIndex`. */
        from: number;
        /** `true` if {@link from} is an NPC (else a player/bot). */
        fromNpc: boolean;
        /** The target's `serverIndex`. */
        to: number;
        /** `true` if {@link to} is a player/bot (else an NPC). */
        toPlayer: boolean;
    }[];
    /** The observer's current dialogue lines, if in a menu. Host UI only. */
    dialog?: string[];
    /** The observer's combat level. */
    combatLvl?: number | null;
    /** Swarm / group tags this observer belongs to. Host UI only. */
    groups?: string[];
}

/** A dead NPC resolved to its static spawn, with a predicted pop window in ticks
 *  (`tMin ≤ pop ≤ t`). Drives the ghost-npc markers. */
export interface NpcRespawn {
    serverIndex: number;
    id: number;
    name: string | null;
    x: number;
    z: number;
    t: number;
    tMin?: number;
    assumed?: boolean;
    checkedAgo?: number;
}

/** A depleted scenery object with a predicted respawn — the scenery mirror of
 *  {@link NpcRespawn}. Each draws a countdown ghost of the object it will become;
 *  the viewer resolves that object's name from the object library. */
export interface ObjectRespawn {
    /** Tile X of the depleted object. */
    x: number;
    /** Absolute tile Z (floor folded in: `z = tileZ + floor*944`). */
    z: number;
    /** The scenery def id the object will respawn as. */
    id: number;
    /** Ticks until it respawns (`0` = due). */
    t: number;
}

/** One static NPC spawn (load order = stable serverIndex). */
export interface NpcSpawnInfo {
    serverIndex: number;
    id: number;
    name: string | null;
    x: number;
    z: number;
    /** The inclusive box it wanders in, z absolute like `z` (bake v21). */
    minX: number;
    minZ: number;
    maxX: number;
    maxZ: number;
}

/** One NPC def (npc-defs.json, bake v22). */
export interface NpcDefInfo {
    id: number;
    name: string | null;
    /** The examine text. */
    description: string | null;
    combatLevel: number;
    hits: number;
    attack: number;
    strength: number;
    defense: number;
    /** The largest melee hit its strength allows (NpcDef.maxHit). */
    maxHit: number;
    attackable: boolean;
    /** The server's isAggressive(): the flag on an attackable NPC. */
    aggressive: boolean;
    ranged: boolean;
    members: boolean;
    /** How long a spawn of it takes to come back in the baked world, in whole seconds: the
     *  def's respawn time, scaled by that world's respawn multiplier and tick. 0: never. */
    respawnSeconds: number;
}

export interface RoutePoint {
    x: number;
    z: number;
    hop: boolean;
}

/** One walked tile of a recorded session's trail (absolute z, floor folded).
 *  Unlike RoutePoint there's no hop flag — teleports are inferred from jumps. */
export interface TrailPoint {
    x: number;
    z: number;
}

export interface SceneryPlacement {
    id: number;
    dir: number;
    x: number;
    z: number;
    floor: number;
}

/** One sprite in the top-down scenery atlas. */
export interface SceneryAtlasEntry {
    id: number;
    dir: number;
    x: number;
    y: number;
    w: number;
    h: number;
    ax: number;
    ay: number;
    ppt: number;
    tw: number;
    th: number;
    name: string;
}

export interface SceneryAtlasIndex {
    version: number;
    entries: SceneryAtlasEntry[];
}

export interface WorldMeshCell {
    a: number;
    b: number;
    plane: number;
    botX0: number;
    botZ0: number;
    kinds: string[];
}

/**
 * The bake format this viewer is written against — {@code
 * WorldMeshExporter.FORMAT_VERSION} at the time of writing. A served tree
 * older than this is missing assets the viewer expects; a host should say so
 * rather than let them fail one 404 at a time.
 *
 * <p>Bump it in lockstep with the baker whenever the viewer starts REQUIRING
 * something new (v18: font-h12b.ttf; v20: engine-exact UVs, face-consistent
 * winding for backface culling, and objlib's {@code translucent} list; v21: each
 * npc-spawns.json spawn's wander box; v22: npc-defs.json). Left
 * behind, this gate silently passes a stale tree — a v19 bake read as current
 * against a required 18 while the viewer was culling geometry the bake hadn't
 * re-wound yet, and nothing on screen said so.
 */
export const REQUIRED_BAKE_VERSION = 22;

export interface WorldMeshManifest {
    version: number;
    baked: number;
    /** The world baked (its server conf's name); absent on a bake from before worlds were stamped,
     *  which were all of {@link UNSTAMPED_WORLD}. */
    world?: string;
    cellTiles: number;
    unitsPerTile: number;
    textures: number;
    botXTiles: number;
    botZTiles: number;
    cells: WorldMeshCell[];
}

/** The world an unstamped bake is of: the authentic one, which every bake was before the stamp. */
export const UNSTAMPED_WORLD = "uranium";

/** Remote-control verbs (mirrors the server's RemoteWalkBus.Action). Kept for
 *  the `sendInteract` signature; no-op in the open-source build. */
export type InteractAction =
    | "object"
    | "object2"
    | "wall_object"
    | "wall_object2"
    | "ground_item"
    | "npc_talk"
    | "npc_attack"
    | "npc_command1"
    | "npc_command2"
    | "player_attack"
    | "player_trade"
    | "player_follow"
    | "player_duel"
    | "answer"
    | "item_command"
    | "item_wield"
    | "item_unwield"
    | "item_drop"
    | "use_item_on_object"
    | "use_item_on_wall_object"
    | "use_item_on_npc"
    | "use_item_on_ground_item"
    | "use_item_on_item";

// ---------------------------------------------------------------------------
// Static asset fetchers (plain GETs answered by a dumb HTTP host)

/** The {@code baked} stamp of the newest manifest this page has read, or null before the first. */
let lastBaked: number | null = null;
let manifestInFlight: Promise<WorldMeshManifest> | null = null;

/**
 * The bake this build was made with ({@code VITE_BAKE}, the manifest's stamp, which
 * {@code build-site.sh} passes to the viewer build it runs after the bake), or empty for a host
 * whose assets can change under a running page — the live runner.
 */
const BAKE: string = import.meta.env.VITE_BAKE ?? "";

/**
 * The bake's manifest, the root every other {@code /api} file is versioned from ({@link versioned}
 * carries its stamp). A static site knows its bake at build time, so the manifest is cached under
 * that stamp like everything else; without one it is revalidated on every read ({@code no-cache}:
 * the browser keeps its copy but asks first), so a new bake is seen at once.
 */
export function fetchWorldMeshManifest(): Promise<WorldMeshManifest> {
    manifestInFlight ??= (
        BAKE
            ? fetch(asset(`/api/world3d/manifest.json?v=${BAKE}`))
            : fetch(asset("/api/world3d/manifest.json"), {cache: "no-cache"})
    )
        .then((res) => {
            if (!res.ok) throw new Error(`world3d manifest: ${res.status}`);
            return res.json() as Promise<WorldMeshManifest>;
        })
        .then((m) => {
            lastBaked = m.baked;
            return m;
        })
        .finally(() => {
            manifestInFlight = null;
        });
    return manifestInFlight;
}

/**
 * {@code path} as {@link asset} places it, plus the bake's stamp as {@code ?v=}: a file is cached
 * for as long as its bake is current, and a new bake asks for new URLs. The stamp is the newest
 * manifest's; the manifest is read first if the page has not read it yet.
 */
export async function versioned(path: string): Promise<string> {
    const baked = lastBaked ?? (await fetchWorldMeshManifest()).baked;
    return withStamp(path, baked);
}

/** {@link versioned} for a caller that cannot wait — the stamp known now (none before the first
 *  manifest, which every view reads before it draws). */
export function versionedNow(path: string): string {
    return lastBaked == null ? asset(path) : withStamp(path, lastBaked);
}

function withStamp(path: string, baked: number): string {
    return `${asset(path)}${path.includes("?") ? "&" : "?"}v=${baked}`;
}

export function worldMeshCellUrl(c: WorldMeshCell, kind: string, baked: number): string {
    return asset(`/api/world3d/cell/c_p${c.plane}_${c.a}_${c.b}_${kind}.bin?v=${baked}`);
}

export function worldMeshTextureUrl(id: number, baked: number): string {
    return asset(`/api/world3d/tex/${id}.png?v=${baked}`);
}

export async function fetchScenery(): Promise<SceneryPlacement[]> {
    const r = await fetch(await versioned("/api/world/scenery.json"));
    if (!r.ok) throw new Error(`/api/world/scenery.json → ${r.status}`);
    return r.json() as Promise<SceneryPlacement[]>;
}

export async function fetchSceneryAtlasIndex(): Promise<SceneryAtlasIndex> {
    const r = await fetch(await versioned("/api/map/scenery-atlas.json"));
    if (!r.ok) throw new Error(`/api/map/scenery-atlas.json → ${r.status}`);
    return r.json() as Promise<SceneryAtlasIndex>;
}

/** One floor's transports, floor-local, in the view's own shape. */
export type FloorTransports = NonNullable<World3DViewProps["transports"]>;

/**
 * One floor's file as TransportsBaker writes it: the world it was baked from, and its transports.
 * A bare array is a bake from before the stamp, which — like an unstamped manifest — was of
 * {@link UNSTAMPED_WORLD}.
 */
type FloorTransportsFile = {world: string; transports: FloorTransports} | FloorTransports;

/**
 * `floor`'s transports as the bake wrote them — none when they were baked for another world than
 * the mesh's: a site never shows one world's transports on another's map.
 */
export async function fetchFloorTransports(floor: number): Promise<FloorTransports> {
    const path = `/api/map/floor/${floor}.transports.json`;
    const [manifest, json] = await Promise.all([
        fetchWorldMeshManifest(),
        versioned(path)
            .then((url) => fetch(url))
            .then((r) => {
                if (!r.ok) throw new Error(`${path} → ${r.status}`);
                return r.json() as Promise<FloorTransportsFile>;
            }),
    ]);
    const file = Array.isArray(json) ? {world: UNSTAMPED_WORLD, transports: json} : json;
    const meshWorld = manifest.world ?? UNSTAMPED_WORLD;
    if (file.world !== meshWorld) {
        console.warn(`[transports] floor ${floor}: baked for ${file.world}, the map is ${meshWorld}`);
        return [];
    }
    return file.transports;
}

export async function fetchNpcSpawns(): Promise<NpcSpawnInfo[]> {
    const r = await fetch(await versioned("/api/world/npc-spawns.json"));
    if (!r.ok) throw new Error(`/api/world/npc-spawns.json → ${r.status}`);
    return r.json() as Promise<NpcSpawnInfo[]>;
}

export async function fetchNpcDefs(): Promise<NpcDefInfo[]> {
    const r = await fetch(await versioned("/api/world/npc-defs.json"));
    if (!r.ok) throw new Error(`/api/world/npc-defs.json → ${r.status}`);
    return r.json() as Promise<NpcDefInfo[]>;
}

export async function fetchWearables(): Promise<Record<number, string[]>> {
    const r = await fetch(await versioned("/api/world/wearables.json"));
    if (!r.ok) throw new Error(`/api/world/wearables.json → ${r.status}`);
    return r.json() as Promise<Record<number, string[]>>;
}

// ---------------------------------------------------------------------------
// Host injection. Everything the viewer FETCHES is static and identical on a
// live host or a baked static host; the only things that differ per deployment
// are the two outbound control verbs. A host wires them in via
// `configureViewerHost`; the open-source demo leaves them no-op (it's view-only).
// (Player sprites need no host hook — they're composited in the browser from the
// per-layer atlas for every deployment; see `playerLayerAtlas`.)

export interface ViewerHost {
    sendWalk?(username: string, tile: {x: number; z: number}): Promise<void>;
    sendInteract?(
        username: string,
        action: InteractAction,
        x: number,
        z: number,
        id?: number,
        dir?: number,
        item?: number,
    ): Promise<void>;
}

let host: ViewerHost = {};

/** Wire a live control source into the viewer. Call once at startup. */
export function configureViewerHost(h: ViewerHost): void {
    host = h;
}

/** Command the selected bot to walk. No-op unless a host injects a live impl. */
export async function sendWalk(username: string, tile: {x: number; z: number}): Promise<void> {
    if (host.sendWalk) return host.sendWalk(username, tile);
}

/** Queue a one-shot interaction. No-op unless a host injects a live impl. */
export async function sendInteract(
    username: string,
    action: InteractAction,
    x: number,
    z: number,
    id = 0,
    dir = 0,
    item = 0,
): Promise<void> {
    if (host.sendInteract) return host.sendInteract(username, action, x, z, id, dir, item);
}
